package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Real;
    in attribute io_3 : Integer;
    attribute elapsedAccumMs : Integer := 0;
    attribute lightThreshold : Real := 0.0;
    attribute tempThreshold : Real := 0.0;
    perform action tick {
      first start;
      then assign elapsedAccumMs := elapsedAccumMs + io_3;
      then if elapsedAccumMs >= 1000 {
        first start;
        then assign elapsedAccumMs := elapsedAccumMs - 1000;
      }
    }
    out attribute io_2 : Boolean = ((io_0 > lightThreshold) or (io_1 > tempThreshold));
    out attribute serial_0_trigger : Boolean = elapsedAccumMs >= 0 and ((io_0 > lightThreshold) or (io_1 > tempThreshold) or true);
    out attribute serial_0_value_0 : Real = io_0;
    out attribute serial_0_value_1 : Real = io_1;
    out attribute serial_1_trigger : Boolean = (io_0 > lightThreshold) or (io_1 > tempThreshold);
    out attribute serial_1_value_0 : Integer = 1;
  }
  part system : Controller;
}
